const CACHE="pocket-partner-8dbf383f67ff", FILES=["./","index.html","style.css","app.js","core.js","core.wasm","manifest.webmanifest","icon-192.png","icon-512.png","assets/001.png","assets/002.png","assets/003.png","assets/004.png","assets/005.png","assets/006.png","assets/007.png","assets/008.png","assets/009.png","assets/010.png","assets/011.png","assets/012.png","assets/013.png","assets/014.png","assets/015.png","assets/016.png","assets/017.png","assets/018.png","assets/025.png","assets/026.png","assets/063.png","assets/064.png","assets/065.png","assets/092.png","assets/093.png","assets/094.png","assets/129.png","assets/130.png","assets/133.png","assets/134.png","assets/135.png","assets/136.png"];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('pocket-partner-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(caches.match(e.request).then(hit=>hit||fetch(e.request)));});
